//! Raw FFI bindings to the DroneCAN [libcanard] core (`canard.c` / `canard.h`).
//!
//! This is a thin `-sys` crate: it compiles the vendored C sources for the
//! target and exposes the auto-generated bindings verbatim. All items are
//! `unsafe` to use and follow the C naming (`canardInit`, `CanardInstance`,
//! `CANARD_OK`, ...). A safe Rust wrapper (and DSDL message types) is expected
//! provided by the `dronecan-core` crate.
//!
//! [libcanard]: https://github.com/dronecan/libcanard
#![no_std]
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]
#![allow(clippy::all)]
// The generated bindgen helper methods (`as_slice`, ...) are `unsafe fn` whose
// bodies do unsafe ops directly; silence the edition-2024 lint for them.
#![allow(unsafe_op_in_unsafe_fn)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

// Compile-time check that the generated struct layout matches the C ABI for the
// selected features/target. Generated by build.rs from `sizeof` values measured
// with the same cross compiler, so it stays correct across feature combinations
// (no hardcoded sizes). A mismatch fails the build instead of corrupting memory.
include!(concat!(env!("OUT_DIR"), "/layout_checks.rs"));
